public static int nullSafeHashCode(long[] array) {
    if (array == null) {
        return 0;
    }

    int hash = 7;
    for (long element : array) {
        hash = 31 * hash + (int) (element ^ (element >>> 32));
    }
    return hash;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    // Get the left child of the node
    TreeNode<T> leftChild = node.getLeft();

    // Set the node's left child to be the right child of its current left child
    node.setLeft(leftChild.getRight());

    // Set the left child's right child to be the node
    leftChild.setRight(node);

    // Return the new parent of the node
    return leftChild;
}

