public static String substVars(String value, Properties props) {
    if (value == null) {
        return null;
    }
    int startIdx = value.indexOf("${");
    if (startIdx == -1) {
        return value;
    }
    int endIdx = value.indexOf("}", startIdx);
    if (endIdx == -1) {
        return value;
    }
    String varName = value.substring(startIdx + 2, endIdx);
    String varValue = props.getProperty(varName);
    if (varValue == null) {
        return value;
    }
    return substVars(value.substring(0, startIdx) + varValue + value.substring(endIdx + 1), props);
}

