private void enlarge(int size) {
    // Calculate the new capacity for the byte vector
    int newCapacity = this.capacity + size;

    // Check if the new capacity is greater than the current capacity
    if (newCapacity > this.capacity) {
        // If so, allocate a new array with the new capacity
        byte[] newArray = new byte[newCapacity];

        // Copy the contents of the current array to the new array
        System.arraycopy(this.array, 0, newArray, 0, this.capacity);

        // Set the new array as the current array
        this.array = newArray;

        // Update the capacity
        this.capacity = newCapacity;
    }
}

