public static String unescapeJava(String str) throws Exception {

    if (str == null) {
        return null;
    }

    StringBuilder sb = new StringBuilder(str.length());
    boolean hadSlash = false;
    char[] arr = str.toCharArray();
    for (int i = 0; i < arr.length; i++) {
        char ch = arr[i];
        if (hadSlash) {
            hadSlash = false;
            switch (ch) {
                case '\\':
                    sb.append('\\');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'b':
                    sb.append('\b');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case '\0':
                    sb.append('\0');
                    break;
                default:
                    sb.append(ch);
                    break;
            }
        } else {
            sb.append(ch);
            if (ch == '\\') {
                hadSlash = true;
            }
        }
    }
    return sb.toString();
}

