private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList() {
    // Initialize the list of minimal separators for every edge in the graph
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();

    // Iterate over every edge in the graph
    for (E edge : graph.edges()) {
        // Compute the minimal separators of the edge in the neighborhood
        List<Pair<Integer,Integer>> minimalSeparators = computeMinimalSeparators(edge);

        // Add the minimal separators to the global separator list
        globalSeparatorList.add(new Pair<>(minimalSeparators, edge));
    }

    return globalSeparatorList;
}

private List<Pair<Integer,Integer>> computeMinimalSeparators(E edge) {
    // Initialize the list of minimal separators
    List<Pair<Integer,Integer>> minimalSeparators = new ArrayList<>();

    // Iterate over every vertex in the graph
    for (V vertex : graph.vertices()) {
        // If the vertex is not adjacent to the edge, continue
        if (!graph.containsEdge(vertex, edge)) {
            continue;
        }

        // Compute the minimal separator of the vertex in the neighborhood of the edge
        Pair<Integer,Integer> minimalSeparator = computeMinimalSeparator(vertex, edge);

        // Add the minimal separator to the list of minimal separators
        minimalSeparators.add(minimalSeparator);
    }

    return minimalSeparators;
}

