private List<Integer> computeLowerBounds(List<K> keys) {
    // Initialize the lower bounds to the minimum value
    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    for (int i = 0; i < keys.size(); i++) {
        lowerBounds.add(Integer.MIN_VALUE);
    }

    // Iterate over the keys and update the lower bounds
    for (int i = 0; i < keys.size(); i++) {
        K key = keys.get(i);
        for (int j = i - 1; j >= 0; j--) {
            if (key.compareTo(keys.get(j)) > 0) {
                lowerBounds.set(i, Math.max(lowerBounds.get(i), lowerBounds.get(j) + 1));
                break;
            }
        }
    }

    return lowerBounds;
}

