Edge edgeToNext() {
    // Check if the current node is virtual
    if (currentNode.isVirtual()) {
        // If so, get the real counterpart of the current node
        Node realCurrentNode = currentNode.getRealCounterpart();
        // Get the next node
        Node nextNode = getNextNode(realCurrentNode);
        // If the next node is also virtual, get its real counterpart
        if (nextNode.isVirtual()) {
            nextNode = nextNode.getRealCounterpart();
        }
        // Return an edge from the real current node to the real next node
        return new Edge(realCurrentNode, nextNode);
    } else {
        // If the current node is not virtual, get the next node
        Node nextNode = getNextNode(currentNode);
        // If the next node is also not virtual, return an edge from the current node to the next node
        if (!nextNode.isVirtual()) {
            return new Edge(currentNode, nextNode);
        } else {
            // If the next node is virtual, get its real counterpart
            nextNode = nextNode.getRealCounterpart();
            // Return an edge from the current node to the real next node
            return new Edge(currentNode, nextNode);
        }
    }
}

